    private static String[] countingSort(String[] arr, int index) {
        int[] count = new int[10];
        for (String s : arr) {
            count[Character.getNumericValue(s.charAt(index))] += 1;
        }
        for (int i = 1; i < 10; i++) {
            count[i] += count[i - 1];
        }
        String[] output = new String[arr.length];
        for (int i = arr.length - 1; i >= 0; i--) {
            output[count[Character.getNumericValue(arr[i].charAt(index))] - 1] = arr[i];
            count[Character.getNumericValue(arr[i].charAt(index))] -= 1;
        }
        return output;
    }
}
