import java.util.Scanner;

class HashSet {
    Integer[] table;
    int size;

    HashSet(int size) {
        this.size = size;
        this.table = new Integer[size];
    }

    int hash(int key) {
        return key % size;
    }

    void put(int value) {
        int index = hash(value);
        for (int i = 0; i < size; i++) {
            int pos = (index + i) % size;
            if (table[pos] == null) {
                table[pos] = value;
                return;
            } else if (table[pos].equals(value)) {
                return; // Valor já existe, não faz nada
            }
        }
        // Se chegou aqui, o conjunto está cheio e não insere o valor
    }

    void remove(int value) {
        int index = hash(value);
        for (int i = 0; i < size; i++) {
            int pos = (index + i) % size;
            if (table[pos] != null && table[pos].equals(value)) {
                table[pos] = null;
                return;
            }
        }
    }

    boolean contains(int value) {
        int index = hash(value);
        for (int i = 0; i < size; i++) {
            int pos = (index + i) % size;
            if (table[pos] != null && table[pos].equals(value)) {
                return true;
            } else if (table[pos] == null) {
                return false; // Se encontrou uma posição vazia, o valor não está no conjunto
            }
        }
        return false;
    }

    void print() {
        System.out.println(java.util.Arrays.toString(table));
    }
}

