class Node<T> {

	private T data;
	private Node<T> right;
	private Node<T> left;
	private int balance;

	public boolean isEmpty() {
		return this.data == null;
	}

	public void setData(T element) {
		this.data = element;
	}

	public void setRight(Node<T> right) {
		this.right = right;
	}

	public void setLeft(Node<T> left) {
		this.left = left;
