```java
import java.util.*;

class Solution {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        int N = in.nextInt(), M = in.nextInt();
        List<List<Integer>> adj = new ArrayList<>();
        for (int i = 0; i < N; i++) adj.add(new ArrayList<>());
        for (int i = 0; i < M; i++) {
            int u = in.nextInt(), v = in.nextInt();
            adj.get(u).add(v);
            adj.get(v).add(u);
        }
        System.out.println(isTree(adj, N));
    }

    static boolean isTree(List<List<Integer>> adj, int N) {
        if (adj.size() != N || N == 0) return false;
        int M = 0;
        for (List<Integer> list : adj) M += list.size();
        M /= 2; // Como o grafo é não direcionado, cada aresta é contada duas vezes
        if (M != N - 1) return false;

        boolean[] visited = new boolean[N];
        if (!dfs(adj, 0, -1, visited)) return false; // Detectou ciclo
        for (boolean b : visited) if (!b) return false; // Não é conectado
        return true;
    }

    static boolean dfs(List<List<Integer>> adj, int node, int parent, boolean[] visited) {
        visited[node] = true;
        for (int neighbor : adj.get(node)) {
            if (!visited[neighbor]) {
                if (!dfs(adj, neighbor, node, visited)) return false;
            } else if (neighbor != parent) {
                return false; // Ciclo detectado
            }
        }
        return true;
    }
}
```

